\label{tab:trajectory}
\begin{tabular}{lccc}
\toprule
\textbf{Metric} & \textbf{Jailbreak} & \textbf{Benign} & \textbf{$p$} \\
\midrule
Monotonicity (mean $\pm$ std) & 0.71 $\pm$ 0.18 & 0.38 $\pm$ 0.14 & 0.003$^*$ \\
Transition Entropy & 1.42 & 2.15 & 0.007$^*$ \\
